import pandas as pd, numpy as np, time
from scipy.optimize import least_squares
from scipy.signal import lfilter, bilinear
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_gentrip_op1.csv','train/A_fault_op1.csv','train/A_line_op3.csv','train/A_load_op2.csv']
dec=5; fs_=1000.0/dec
D={f:pd.read_csv(f).iloc[::dec].reset_index(drop=True) for f in files}
def build(p,n):
    den=np.concatenate([[1.0],p[:n]])            # monic, s^n + a1 s^(n-1)+...
    nums={}
    i=n
    for out in ['P','Q']:
        for inp in ['V','Vs','th']:
            nums[(out,inp)]=p[i:i+n+1]; i+=n+1
    return den,nums
def simf(p,n,d):
    den,nums=build(p,n)
    V=d.voltage_pu.values; th=d.bus_angle_rad.values; Vs=d.voltage_setpoint_pu.values
    U={'V':V-V[0],'Vs':Vs-Vs[0],'th':th-th[0]}
    res={}
    for out in ['P','Q']:
        y=0
        for inp in ['V','Vs','th']:
            num=nums[(out,inp)]
            bz,az=bilinear(num,den,fs_)
            y=y+lfilter(bz,az,U[inp])
        res[out]=y
    return res['P']+d.active_power_pu.values[0], res['Q']+d.reactive_power_pu.values[0]
def resid(p,n,fl):
    out=[]
    for f in fl:
        d=D[f]; P,Q=simf(p,n,d)
        out.append(P-d.active_power_pu.values); out.append(Q-d.reactive_power_pu.values)
    return np.concatenate(out)
t0=time.time()
res_store={}
for n in [1,2,3]:
    npar=n+6*(n+1)
    best=None
    for trial in range(6):
        rng=np.random.default_rng(trial)
        p0=rng.normal(0,0.3,npar)
        p0[:n]=np.abs(rng.normal(0,1,n))*np.array([1.0]*n)+0.5
        try:
            r=least_squares(resid,p0,args=(n,['train/A_vref_op1.csv','train/A_vref_op3.csv']),max_nfev=200)
        except Exception as e:
            continue
        if best is None or r.cost<best.cost: best=r
    rm=np.sqrt(np.mean(best.fun**2))
    print('n',n,'rms',rm, 'poles',np.roots(np.concatenate([[1],best.x[:n]])), time.time()-t0)
    res_store[n]=best.x
np.save('tf_fits.npy',res_store,allow_pickle=True)

