def bilin(num,den,fs):
    n=len(den)-1; c=2*fs
    Zm=np.poly1d([1,-1]); Zp=np.poly1d([1,1])
    def tf(coef):
        tot=np.poly1d([0.]); L=len(coef)-1
        for j,cj in enumerate(coef):
            sp=L-j; tot=tot+cj*(c**sp)*(Zm**sp)*(Zp**(n-sp))
        return tot.coeffs
    nz=tf(np.concatenate([np.zeros(n+1-len(num)),num])); dz=tf(den)
    nz=np.concatenate([np.zeros(n+1-len(nz)),nz]); dz=np.concatenate([np.zeros(n+1-len(dz)),dz])
    return nz/dz[0], dz/dz[0]
